        self.lastDisconnectedAtMs = lastDisconnectedAtMs
        self.lastSeenAtMs = lastSeenAtMs
        self.lastDeliveredAtMs = lastDeliveredAtMs
        self.lastReceivedAtMs = lastReceivedAtMs
    }
}



