        if lhs.payload != rhs.payload {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(chatId)
        hasher.combine(senderUserId)
        hasher.combine(lamport)
        hasher.combine(timestamp)
        hasher.combine(kind)
        hasher.combine(payload)
    }
}


